import type { LucideIcon } from "lucide-react";
import { Coins, Gauge, Crown, PieChart, Award, Flame } from "lucide-react";

// Phase 3A — MPGR Agent frontend foundation. Everything here is local/mock:
// no OpenAI, Claude, Gemini, or backend calls. Replies are generated by
// simple keyword matching against the app's own feature set so the chat
// feels on-brand while the page is honest about being a local preview.
//
// Phase 3B swap point: `generateAgentReply` becomes the one function that
// gets replaced with a real model call; nothing else in this module or the
// hook/UI layer needs to change shape.

export type AgentStatusId = "online" | "thinking" | "beta";

