const FALLBACK_REPLIES = [
  "I'm running in local preview mode right now, so I can only point you in the right direction — full reasoning connects in a future phase. Try asking about XP, staking, Holder Tier, Premium, or your portfolio.",
  "That's outside what I can answer in this local preview. I can currently help with XP, staking, Holder Tier, Premium, and Season Pass questions.",
];

interface ReplyRule {
  keywords: string[];
  reply: string;
}

const REPLY_RULES: ReplyRule[] = [
  {
    keywords: ["xp", "level", "streak"],
    reply:
      "Your XP and level progress live on your Profile and Dashboard — daily check-ins, achievements, and referrals are the fastest ways to climb. Once I'm connected to live data, I'll be able to read your exact XP total and streak here.",
  },
  {
    keywords: ["stak", "lock"],
    reply:
      "Staking lets you lock MPGR for a chosen duration to earn rewards, shown on the Staking page along with your active positions and claimable rewards. Longer lock durations generally earn a stronger rate — head to Staking to see your live options.",
  },
  {
    keywords: ["holder", "tier"],
    reply:
      "Holder Tier is based on your combined wallet, staked, and locked MPGR — it drives your badge, governance voting weight, and community reputation. Check the Holder Tier section on your Dashboard or Profile to see your score and progress to the next tier.",
  },
  {
    keywords: ["premium", "subscription", "membership"],
    reply:
      "MPGR Premium boosts your XP and Rewards multipliers and unlocks premium cosmetics across the app. Visit the Premium page to compare tiers and see your current multiplier.",
  },
  {
    keywords: ["portfolio", "balance", "wallet"],
    reply:
      "Your Portfolio Overview on the Dashboard breaks down wallet, staked, and locked MPGR alongside claimable rewards. That's the best place to see your full holdings at a glance.",
  },
  {
    keywords: ["season", "pass"],
    reply:
      "The Season Pass tracks seasonal points toward level rewards shown on the Season Pass page. Play, stake, and stay active during the season to keep climbing the track.",
  },
  {
    keywords: ["reward", "claim"],
    reply:
      "Claimable rewards from staking, achievements, and events show up on the Rewards page. Anything claimable there is ready to collect right now.",
  },
  {
    keywords: ["hello", "hi", "hey"],
    reply: "Hey! I'm the MPGR Agent — ask me about your XP, staking, Holder Tier, Premium, or portfolio.",
  },
];

export function generateAgentReply(prompt: string): string {
  const normalized = prompt.toLowerCase();
  const match = REPLY_RULES.find((rule) => rule.keywords.some((kw) => normalized.includes(kw)));
  if (match) return match.reply;
  return FALLBACK_REPLIES[Math.floor(Math.random() * FALLBACK_REPLIES.length)];
}
